// Precache with a few requests at a time and retries (a burst of 100 parallel requests can be dropped by a small
// server); one file that still fails fails the install, and the old version stays in charge.
async function precache() {
  const c = await caches.open(CACHE);
  const queue = PRECACHE.slice();
  const one = async (p) => {
    for (let i = 0; i < 4; i++) {
      try {
        const res = await fetch(new Request(p, { cache: 'reload' }));
        if (res.ok) { await c.put(p, res); return; }
      } catch (e) { /* retry */ }
      await new Promise((r) => setTimeout(r, 250 * (i + 1)));
    }
    throw new Error('could not cache ' + p);
  };
  await Promise.all(Array.from({ length: 6 }, async () => { while (queue.length) await one(queue.shift()); }));
}

self.addEventListener('install', (e) => { e.waitUntil(precache()); });

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('usaaio-prep-') && k !== CACHE && k !== PY_CACHE) await caches.delete(k);
    await self.clients.claim();
  })());
});

self.addEventListener('message', (e) => {
  if (e.data === 'skipWaiting') self.skipWaiting();
  if (e.data === 'version' && e.source) e.source.postMessage({ version: VERSION });
});

async function fromCache(cacheName, req, { ignoreSearch = false } = {}) {
  const c = await caches.open(cacheName);
  const hit = await c.match(req, { ignoreSearch });
  if (hit) return hit;
  const res = await fetch(req);
  if (res.ok && (res.type === 'basic' || res.type === 'cors')) c.put(req, res.clone());
  return res;
}

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin === self.location.origin) {
    if (!url.pathname.startsWith(new URL(self.registration.scope).pathname)) return;
    e.respondWith(fromCache(CACHE, req, { ignoreSearch: req.mode === 'navigate' }).catch(async () => {
      if (req.mode === 'navigate') return (await caches.match('app.html')) || Response.error();
      return Response.error();
    }));
  } else if (url.href.startsWith(PYODIDE)) {
    e.respondWith(fromCache(PY_CACHE, req));
  }
});
